use maho_rpc::{session_worker_client::receive_reservation,session_worker_protocol::{SessionWorkerToHost,SessionWriteGrant},session_worker_signals::WorkerSignal};
#[test]fn stopped_host_denies_blocked_reservation_without_callback(){let signal=WorkerSignal::default();assert!(receive_reservation(SessionWorkerToHost::Reserve{path:"/path".into(),signal:signal.clone()},true,|_|panic!("stopped worker cannot reserve")).is_none());assert_eq!(signal.wait(std::time::Duration::ZERO),2);}
#[test]fn host_reservation_limit_releases_worker_with_domain_code(){let signal=WorkerSignal::default();let worker=signal.clone();let(send,receive)=std::sync::mpsc::channel();let thread=std::thread::spawn(move||{send.send(SessionWorkerToHost::Reserve{path:"/path".into(),signal:worker.clone()}).unwrap();worker.wait(std::time::Duration::from_secs(2))});let message=receive.recv_timeout(std::time::Duration::from_secs(2)).unwrap();assert!(receive_reservation(message,false,|path|{assert_eq!(path,"/path");SessionWriteGrant::Limit}).is_none());assert_eq!(thread.join().unwrap(),3);}
